{
  "ref": "spec:openapi",
  "content": {
    "format": "openapi-3.1",
    "title": "RailGrid Systems \u2014 fleet maintenance orchestration API for regional freight rail operators API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the RailGrid Systems \u2014 fleet maintenance orchestration API for regional freight rail operators API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "RailGrid Systems \u2014 fleet maintenance orchestration API for regional freight rail operators API",
        "version": "1.0.0",
        "description": "RailGrid Orchestrator API: schedules locomotive inspections, opens maintenance work orders, attaches inspection findings, and commits closeout reports against rolling stock."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v2/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v2/inspections": {
          "post": {
            "summary": "Create an inspection (mints inspection_id)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/inspections/{id}": {
          "get": {
            "summary": "Fetch inspection state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/work-orders": {
          "post": {
            "summary": "Open a work order against an inspection",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/work-orders/{id}": {
          "get": {
            "summary": "Fetch work order incl. committed_count partial state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/work-orders/{id}/findings": {
          "post": {
            "summary": "Attach findings to a work order",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/work-orders/{id}/commit": {
          "post": {
            "summary": "Commit closeout (partial-write trap)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/work-orders/{id}/closeout": {
          "get": {
            "summary": "Verify final closeout state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v1/work-orders": {
          "post": {
            "summary": "DEPRECATED legacy work-order open",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-07-18T17:09:29.585408+00:00"
}

